package main

import "fmt"

func main() {
	x := 10 // x is in main's function block
	fmt.Println("outer x:", x)

	{
		// A bare block opens a new nested scope.
		y := 20 // y is only visible inside this block
		x = x + y // '=' assigns to the OUTER x (no new variable)
		fmt.Println("inside block, x:", x, "y:", y)
	} // y goes out of scope here

	// fmt.Println(y) // would not compile: undefined: y

	// Redeclaration rule: ':=' is allowed when at least ONE name is new.
	a, b := 1, 2
	a, c := 100, 3 // a is reused (assigned), c is new -> legal
	fmt.Println("a:", a, "b:", b, "c:", c)

	// a, b := 5, 6 // would NOT compile: no new variables on left side of :=

	fmt.Println("final x:", x)
}

package main

import (
	"errors"
	"fmt"
)

// parse returns a value and an error; negative input is an error.
func parse(n int) (int, error) {
	if n < 0 {
		return 0, errors.New("negative input")
	}
	return n * 2, nil
}

// buggy: the inner ':=' shadows the outer err, so the caller's err stays nil.
func buggy(n int) (result int, err error) {
	if n%2 == 0 {
		// BUG: ':=' here declares a NEW err scoped to the if-block.
		// The named return 'err' is never assigned.
		result, err := parse(n) // shadows both result and err
		fmt.Println("  inner saw err:", err, "result:", result)
	}
	return // returns the OUTER result(0) and err(nil) -- error lost!
}

// fixed: assign to the outer named returns with '='.
func fixed(n int) (result int, err error) {
	if n%2 == 0 {
		result, err = parse(n) // '=' updates the named returns
		if err != nil {
			return 0, err
		}
	}
	return result, err
}

func main() {
	r, err := buggy(-4)
	fmt.Printf("buggy(-4) => result=%d err=%v (error was SWALLOWED)\n", r, err)

	r, err = fixed(-4)
	fmt.Printf("fixed(-4) => result=%d err=%v (error propagated)\n", r, err)
}

package main

import "fmt"

func main() {
	words := []string{"go", "scope", "shadow"}

	// for-init: i is scoped to the for statement only.
	for i := 0; i < len(words); i++ {
		// if-init: w is scoped to this if (condition + branches).
		if w := words[i]; len(w) > 2 {
			fmt.Printf("index %d: %q is long\n", i, w)
		} else {
			fmt.Printf("index %d: %q is short\n", i, w)
		}
		// w is out of scope here; i still in scope inside the loop.
	}
	// i and w are both out of scope here.

	// switch-init: kind is scoped to the whole switch.
	switch kind := classify(7); kind {
	case "odd":
		fmt.Println("7 is", kind)
	default:
		fmt.Println("7 is", kind)
	}

	// Universe-block shadowing footgun: a local named 'len'
	// hides the builtin len inside this block.
	{
		len := 42 // shadows the builtin len in this block!
		fmt.Println("shadowed len value:", len)
		// len(words) // would NOT compile here: cannot call non-function len (int)
	}
	fmt.Println("builtin len works again:", len(words))
}

func classify(n int) string {
	if n%2 == 0 {
		return "even"
	}
	return "odd"
}
